int process_dref_atom(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries_count;
    int ret;

    if (!c || !pb || !c->nb_streams) {
        return AVERROR(EINVAL);
    }

    entries_count = avio_rb32(pb);
    if (entries_count < 0) {
        return AVERROR_INVALIDDATA;
    }

    if (entries_count > 1024) {
        return AVERROR_INVALIDDATA;
    }

    for (i = 0; i < entries_count; i++) {
        uint32_t type = avio_rl32(pb);
        int size = avio_rb32(pb);

        if (size < 0) {
            return AVERROR_INVALIDDATA;
        }

        if (size > atom.size - 8) {
            return AVERROR_INVALIDDATA;
        }

        switch (type) { 
            case MKTAG('a','l','i','s'):
                ret = handle_alias_record(pb, size);
                if (ret < 0) {
                    return ret;
                }
                break;
            default:
                avio_skip(pb, size - 8);
                break;
        }
    }

    return 0;
}

int handle_alias_record(AVIOContext *pb, int size) {
    if (!pb || size < 0) {
        return AVERROR(EINVAL);
    }

    avio_skip(pb, 4);
    size -= 4;

    while (size > 0) {
        int record_size = avio_rb16(pb);
        if (record_size < 0 || record_size > size) {
            return AVERROR_INVALIDDATA;
        }

        avio_skip(pb, record_size - 2);
        size -= record_size;
    }

    return 0;
}
